        foreach ($data as $lgaCode => $wardMap) {
            $lga = Lga::where('code', $lgaCode)->firstOrFail();

            foreach ($wardMap as $wardCode => $stationNames) {
                $ward = Ward::where('code', $wardCode)->firstOrFail();

                $rows = [];
                $now  = now();
                foreach ($stationNames as $idx => $name) {
                    $rows[] = [
                        'name'       => $name,
                        'code'       => $wardCode . '-' . str_pad($idx + 1, 2, '0', STR_PAD_LEFT),
                        'ward_id'    => $ward->id,
                        'lga_id'     => $lga->id,
                        'created_at' => $now,
                        'updated_at' => $now,
                    ];
                }

                PollingStation::upsert($rows, ['code'], ['name', 'ward_id', 'lga_id', 'updated_at']);
            }
        }
    }
